impl XMTIntegrateReportT {
    pub fn pack<'b, A: ::flatbuffers::Allocator + 'b>(
        &self,
        _fbb: &mut ::flatbuffers::FlatBufferBuilder<'b, A>
    ) -> ::flatbuffers::WIPOffset<XMTIntegrateReport<'b>> {
        let AS_OF_MS = self.AS_OF_MS;
        let SELECTION = self.SELECTION.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let MANEUVERS = self.MANEUVERS.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let CATALOG_RECORDS = self.CATALOG_RECORDS;
        let OMM_RECORDS = self.OMM_RECORDS;
        let OCM_RECORDS = self.OCM_RECORDS;
        let MNV_RECORDS = self.MNV_RECORDS;
        let SELECTED_COUNT = self.SELECTED_COUNT;
        let STALE_COUNT = self.STALE_COUNT;
        let NO_PRODUCT_COUNT = self.NO_PRODUCT_COUNT;
        let UNMEASURED_COUNT = self.UNMEASURED_COUNT;
        let WITHOUT_OCM_COUNT = self.WITHOUT_OCM_COUNT;
        let MANEUVERABLE_COUNT = self.MANEUVERABLE_COUNT;
        let MANEUVER_EVENT_COUNT = self.MANEUVER_EVENT_COUNT;
        let MERGED_EVENT_COUNT = self.MERGED_EVENT_COUNT;
        let UNLINKED_COUNTS = self.UNLINKED_COUNTS.as_ref().map(|x|{
            let w: alloc::vec::Vec<_> = x.iter().map(|t| t.pack(_fbb)).collect();_fbb.create_vector(&w)
        });
        let REFUSED_COUNT = self.REFUSED_COUNT;
        let IDENTITY = self.IDENTITY.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let OBJECTS = self.OBJECTS.as_ref().map(|x|{
            let w: alloc::vec::Vec<_> = x.iter().map(|t| t.pack(_fbb)).collect();_fbb.create_vector(&w)
        });
        let UNLINKED = self.UNLINKED.as_ref().map(|x|{
            let w: alloc::vec::Vec<_> = x.iter().map(|t| t.pack(_fbb)).collect();_fbb.create_vector(&w)
        });
        let REFUSED = self.REFUSED.as_ref().map(|x|{
            let w: alloc::vec::Vec<_> = x.iter().map(|t| t.pack(_fbb)).collect();_fbb.create_vector(&w)
        });
        XMTIntegrateReport::create(_fbb, &XMTIntegrateReportArgs{
            AS_OF_MS,
            SELECTION,
            MANEUVERS,
            CATALOG_RECORDS,
            OMM_RECORDS,
            OCM_RECORDS,
            MNV_RECORDS,
            SELECTED_COUNT,
            STALE_COUNT,
            NO_PRODUCT_COUNT,
            UNMEASURED_COUNT,
            WITHOUT_OCM_COUNT,
            MANEUVERABLE_COUNT,
            MANEUVER_EVENT_COUNT,
            MERGED_EVENT_COUNT,
            UNLINKED_COUNTS,
            REFUSED_COUNT,
            IDENTITY,
            OBJECTS,
            UNLINKED,
            REFUSED,
        })
    }
}

