#[derive(Debug, Clone, PartialEq)]
pub struct XMTT {
    pub MATCH_REQUEST: Option<alloc::boxed::Box<XMTMatchRequestT>>,
    pub MATCH_REPORT: Option<alloc::boxed::Box<XMTMatchReportT>>,
    pub COMPOSE_RECIPE: Option<alloc::boxed::Box<XMTComposeRecipeT>>,
    pub COMPOSE_REPORT: Option<alloc::boxed::Box<XMTComposeReportT>>,
    pub INTEGRATE_RECIPE: Option<alloc::boxed::Box<XMTIntegrateRecipeT>>,
    pub INTEGRATE_REPORT: Option<alloc::boxed::Box<XMTIntegrateReportT>>,
    pub EPOCH_FIT_POLICY: Option<alloc::boxed::Box<XMTEpochFitPolicyT>>,
    pub EPOCH_FIT_REPORT: Option<alloc::boxed::Box<XMTEpochFitReportT>>,
}

impl Default for XMTT {
    fn default() -> Self {
        Self {
            MATCH_REQUEST: None,
            MATCH_REPORT: None,
            COMPOSE_RECIPE: None,
            COMPOSE_REPORT: None,
            INTEGRATE_RECIPE: None,
            INTEGRATE_REPORT: None,
            EPOCH_FIT_POLICY: None,
            EPOCH_FIT_REPORT: None,
        }
    }
}

impl XMTT {
    pub fn pack<'b, A: ::flatbuffers::Allocator + 'b>(
        &self,
        _fbb: &mut ::flatbuffers::FlatBufferBuilder<'b, A>
    ) -> ::flatbuffers::WIPOffset<XMT<'b>> {
        let MATCH_REQUEST = self.MATCH_REQUEST.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let MATCH_REPORT = self.MATCH_REPORT.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let COMPOSE_RECIPE = self.COMPOSE_RECIPE.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let COMPOSE_REPORT = self.COMPOSE_REPORT.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let INTEGRATE_RECIPE = self.INTEGRATE_RECIPE.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let INTEGRATE_REPORT = self.INTEGRATE_REPORT.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let EPOCH_FIT_POLICY = self.EPOCH_FIT_POLICY.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let EPOCH_FIT_REPORT = self.EPOCH_FIT_REPORT.as_ref().map(|x|{
            x.pack(_fbb)
        });
        XMT::create(_fbb, &XMTArgs{
            MATCH_REQUEST,
            MATCH_REPORT,
            COMPOSE_RECIPE,
            COMPOSE_REPORT,
            INTEGRATE_RECIPE,
            INTEGRATE_REPORT,
            EPOCH_FIT_POLICY,
            EPOCH_FIT_REPORT,
        })
    }
}

/// Verifies that a buffer of bytes contains a `XMT`
/// and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_xmt_unchecked`.
#[inline]
pub fn root_as_xmt(buf: &[u8]) -> Result<XMT<'_>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::root::<XMT>(buf)
}

/// Verifies that a buffer of bytes contains a size prefixed
/// `XMT` and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `size_prefixed_root_as_xmt_unchecked`.
#[inline]
pub fn size_prefixed_root_as_xmt(buf: &[u8]) -> Result<XMT<'_>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::size_prefixed_root::<XMT>(buf)
}

/// Verifies, with the given options, that a buffer of bytes
/// contains a `XMT` and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_xmt_unchecked`.
#[inline]
pub fn root_as_xmt_with_opts<'b, 'o>(
    opts: &'o ::flatbuffers::VerifierOptions,
    buf: &'b [u8],
) -> Result<XMT<'b>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::root_with_opts::<XMT<'b>>(opts, buf)
}

/// Verifies, with the given verifier options, that a buffer of
/// bytes contains a size prefixed `XMT` and returns
/// it. Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_xmt_unchecked`.
#[inline]
pub fn size_prefixed_root_as_xmt_with_opts<'b, 'o>(
    opts: &'o ::flatbuffers::VerifierOptions,
    buf: &'b [u8],
) -> Result<XMT<'b>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::size_prefixed_root_with_opts::<XMT<'b>>(opts, buf)
}

/// Assumes, without verification, that a buffer of bytes contains a XMT and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid `XMT`.
#[inline]
pub unsafe fn root_as_xmt_unchecked(buf: &[u8]) -> XMT<'_> {
    unsafe { ::flatbuffers::root_unchecked::<XMT>(buf) }
}

/// Assumes, without verification, that a buffer of bytes contains a size prefixed XMT and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid size prefixed `XMT`.
#[inline]
pub unsafe fn size_prefixed_root_as_xmt_unchecked(buf: &[u8]) -> XMT<'_> {
    unsafe { ::flatbuffers::size_prefixed_root_unchecked::<XMT>(buf) }
}

pub const XMT_IDENTIFIER: &str = "$XMT";

#[inline]
pub fn xmt_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, XMT_IDENTIFIER, false)
}

#[inline]
pub fn xmt_size_prefixed_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, XMT_IDENTIFIER, true)
}

#[inline]
pub fn finish_xmt_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<XMT<'a>>
) {
    fbb.finish(root, Some(XMT_IDENTIFIER));
}

#[inline]
pub fn finish_size_prefixed_xmt_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<XMT<'a>>
) {
    fbb.finish_size_prefixed(root, Some(XMT_IDENTIFIER));
}
